 "content": "def transform(grid):
    # The 5s form overlapping outlined pixel shapes. Their interiors are
    # filled according to local 3x3 blocks: classify zeros enclosed by a
    # complete-ish 5 boundary; 7 denotes the small 2x2 pocket, 8 larger fill.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Use the demonstrated motif geometrically: zero cells within a region
    # bounded by nearby 5s are interior fill; tiny pockets (area <= 4) are 7.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]; edge=False
            while stack:
                x,y=stack.pop(); cells.append((x,y))
                edge |= x==0 or y==0 or x==h-1 or y==w-1
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<h and 0<=ny<w and grid[nx][ny]==0 and (nx,ny) not in seen:
                        seen.add((nx,ny)); stack.append((nx,ny))
            if not edge:
                comps.append(cells)
    for cells in comps:
        color = 7 if len(cells) <= 4 else 8
        for r,c in cells: out[r][c]=color
    # For narrow test boards, local 3x3 cavities may be open to the edge by
    # one-cell gaps; identify fully bounded zero pockets using neighbor counts.
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r][c] == 0:
                around=[grid[r+dr][c+dc] for dr,dc in ((-1,0),(1,0),(0,-1),(0,1))]
                if sum(v==5 for v in around)>=3:
                    out[r][c]=8
    return out

assert callable(transform)
